@import url("https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700;800&family=Cinzel+Decorative:wght@700&family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,400;1,600&family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap");

:root {
  /* Altar Gothic Palette */
  --ink: #0d0d11;
  --ink2: #141318;
  --stone: #1c1a1f;
  --stone2: #26222b;
  --gold: #c5a059;
  --gold2: #f0d59a;
  --gold-dim: #77552e;
  --crimson: #8b1e2d;
  --crimson2: #a52c30;
  --wine: #4a121a;
  --paper: #e8d5b5;
  --paper2: #cdb78e;
  --cream: #f7ebd2;
  --muted: #a99b82;
  --green: #7e9272;
  --blue: #758a9a;
  --line: rgba(197, 160, 89, 0.35);
  --line-strong: rgba(197, 160, 89, 0.65);
  --shadow: 0 20px 60px rgba(0, 0, 0, 0.75);
  --glow-gold: 0 0 24px rgba(197, 160, 89, 0.35);

  /* Font Stacks */
  --serif: "Cormorant Garamond", Georgia, serif;
  --display: "Cinzel", Georgia, serif;
  --display-decorative: "Cinzel Decorative", Georgia, serif;
  --sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --mono: "JetBrains Mono", monospace;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  background-color: var(--ink);
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.6;
  background-image:
    radial-gradient(ellipse at 50% -10%, rgba(139, 30, 45, 0.22), transparent 55%),
    radial-gradient(circle at 80% 30%, rgba(197, 160, 89, 0.12), transparent 50%),
    linear-gradient(
      90deg,
      rgba(0, 0, 0, 0.4),
      transparent 20%,
      transparent 80%,
      rgba(0, 0, 0, 0.4)
    );
  background-attachment: fixed;
  min-height: 100vh;
}

/* Typography Helpers */
.display {
  font-family: var(--display);
}
.display-decorative {
  font-family: var(--display-decorative);
}
.serif {
  font-family: var(--serif);
}
.mono {
  font-family: var(--mono);
}
.gold {
  color: var(--gold2);
}
.crimson {
  color: var(--crimson2);
}
.muted {
  color: var(--muted);
}
.cream {
  color: var(--cream);
}

.eyebrow {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
}

/* Accessibility Focus Ring */
button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--gold2);
  outline-offset: 3px;
}

/* Interactive Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid var(--gold-dim);
  background: linear-gradient(180deg, #8b1e2d, #521019);
  color: #f7ebd2;
  padding: 12px 22px;
  border-radius: 3px;
  font-family: var(--display);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.5);
  cursor: pointer;
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
  text-decoration: none;
}

.btn:hover {
  transform: translateY(-2px);
  border-color: var(--gold2);
  filter: brightness(1.2);
  box-shadow: 0 8px 25px rgba(197, 160, 89, 0.35);
  color: #ffffff;
}

.btn:active {
  transform: translateY(0);
}

.btn.secondary {
  background: rgba(28, 26, 31, 0.9);
  border-color: #9c7b48;
  color: #e8d5b5;
}

.btn.secondary:hover {
  border-color: var(--gold2);
  background: rgba(38, 34, 43, 0.95);
  color: #fff;
}

.btn.ghost {
  background: transparent;
  border-color: rgba(197, 160, 89, 0.35);
  color: var(--muted);
  box-shadow: none;
}

.btn.ghost:hover {
  color: var(--cream);
  border-color: var(--gold);
}

.btn.small {
  padding: 8px 14px;
  font-size: 10px;
}

/* Panels & Containers */
.panel {
  border: 1px solid var(--line);
  background: linear-gradient(145deg, rgba(30, 26, 33, 0.94), rgba(16, 14, 18, 0.98));
  box-shadow: var(--shadow);
  position: relative;
  border-radius: 4px;
  padding: 24px;
}

.panel::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 1px solid rgba(197, 160, 89, 0.16);
  pointer-events: none;
  border-radius: 2px;
}

.panel.paper {
  background: linear-gradient(145deg, #e8d5b5, #c8ad7e);
  color: #23180f;
  border-color: #8c6837;
}

.panel.paper::before {
  border-color: rgba(100, 70, 35, 0.28);
}

.divider {
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold), transparent);
  margin: 24px 0;
}

/* Tag / Badge */
.tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid #8c6b39;
  padding: 4px 10px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #f7ebd2;
  background: #211710;
  border-radius: 2px;
}

.tag.red {
  border-color: #8e3536;
  color: #f0b9ad;
  background: #3a1114;
}

.tag.green {
  border-color: #5c7656;
  color: #c3d4b8;
  background: #19251a;
}

.tag.gold {
  border-color: #c5a059;
  color: #f0d59a;
  background: #2b1f11;
}

/* Keyframe animations */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-fade-in {
  animation: fadeIn 0.4s ease-out forwards;
}

@keyframes candleFlicker {
  0%,
  100% {
    filter: drop-shadow(0 0 10px rgba(240, 213, 154, 0.4));
    opacity: 0.95;
  }
  50% {
    filter: drop-shadow(0 0 20px rgba(240, 213, 154, 0.75));
    opacity: 1;
  }
}

.candle-glow {
  animation: candleFlicker 3.5s infinite ease-in-out;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

import React, { useState } from "react";

export interface NavigationProps {
  currentRoute: string;
  onRouteChange: (route: string, params?: Record<string, string>) => void;
  onOpenDemoModal?: () => void;
}

export const TopBar: React.FC<NavigationProps> = ({
  currentRoute,
  onRouteChange,
  onOpenDemoModal,
}) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const navItems = [
    { id: "landing", label: "Archive" },
    { id: "dashboard", label: "Investigator" },
    { id: "archive", label: "Chambers" },
    { id: "upload", label: "Intake" },
    { id: "integrations", label: "Integrations" },
    { id: "setup", label: "AI Profile" },
    { id: "spirit", label: "Free Spirit" },
    { id: "about", label: "Safety" },
  ];

  const handleNav = (id: string) => {
    onRouteChange(id);
    setMobileMenuOpen(false);
  };

  return (
    <header
      style={{
        height: "86px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: "16px",
        padding: "10px clamp(16px, 3vw, 42px)",
        borderBottom: "1px solid rgba(197, 160, 89, 0.35)",
        background: "linear-gradient(180deg, rgba(13, 13, 17, 0.96), rgba(8, 8, 10, 0.98))",
        position: "sticky",
        top: 0,
        zIndex: 50,
        backdropFilter: "blur(14px)",
      }}
    >
      {/* Brand logo + Title */}
      <div
        onClick={() => handleNav("landing")}
        style={{
          display: "flex",
          alignItems: "center",
          gap: "12px",
          cursor: "pointer",
          minWidth: "250px",
        }}
      >
        <img
          src="/logo.png"
          alt="Keys of the Departed emblem"
          style={{
            width: "50px",
            height: "54px",
            objectFit: "contain",
            filter: "drop-shadow(0 0 10px rgba(197, 160, 89, 0.35))",
          }}
        />
        <div>
          <div
            className="display"
            style={{
              fontSize: "17px",
              fontWeight: 700,
              letterSpacing: "0.06em",
              color: "#f7ebd2",
              textShadow: "0 2px 4px rgba(0,0,0,0.9)",
              lineHeight: 1.1,
            }}
          >
            KEYS OF THE DEPARTED
          </div>
          <div
            className="serif"
            style={{
              fontSize: "12px",
              fontStyle: "italic",
              color: "#c7b591",
              marginTop: "2px",
            }}
          >
            The engineer left. Their access didn't.
          </div>
        </div>
      </div>

      {/* Decorative Swatches from Reference */}
      <div
        className="swatches-bar"
        style={{
          display: "flex",
          gap: "8px",
          alignItems: "center",
          paddingRight: "14px",
          borderRight: "1px solid rgba(197, 160, 89, 0.25)",
        }}
      >
        {[
          { color: "#c5a059", name: "Gold" },
          { color: "#403a32", name: "Stone" },
          { color: "#8b1e2d", name: "Crimson" },
          { color: "#141318", name: "Midnight" },
          { color: "#e8d5b5", name: "Parchment" },
        ].map((swatch, idx) => (
          <div key={idx} style={{ display: "flex", flexDirection: "column", alignItems: "center" }} title={swatch.name}>
            <div
              style={{
                width: "18px",
                height: "18px",
                borderRadius: "50%",
                background: swatch.color,
                border: "1px solid rgba(255, 255, 255, 0.2)",
                boxShadow: "inset 0 0 4px rgba(0,0,0,0.4)",
              }}
            />
            <span
              className="mono"
              style={{ fontSize: "7px", textTransform: "uppercase", color: "#a99b82", marginTop: "2px" }}
            >
              {swatch.name}
            </span>
          </div>
        ))}
      </div>

      {/* Main Desktop Nav Links */}
      <nav className="desktop-nav" style={{ display: "flex", alignItems: "center", gap: "4px" }}>
        {navItems.map((item) => {
          const isActive = currentRoute === item.id;
          return (
            <button
              key={item.id}
              onClick={() => handleNav(item.id)}
              className="display"
              style={{
                background: "transparent",
                border: "none",
                borderBottom: isActive ? "2px solid var(--gold)" : "2px solid transparent",
                color: isActive ? "var(--gold2)" : "#c8b994",
                padding: "8px 10px",
                fontSize: "11px",
                fontWeight: 600,
                letterSpacing: "0.06em",
                textTransform: "uppercase",
                cursor: "pointer",
                transition: "all 0.2s ease",
              }}
            >
              {item.label}
            </button>
          );
        })}
      </nav>

      {/* Right Actions */}
      <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
        {onOpenDemoModal && (
          <button
            onClick={onOpenDemoModal}
            className="btn small"
            style={{
              background: "linear-gradient(180deg, #8b1e2d, #521019)",
              borderColor: "var(--gold)",
              boxShadow: "0 0 14px rgba(139, 30, 45, 0.4)",
              whiteSpace: "nowrap",
