            </button>
          ))}
          <div style={{ display: "flex", gap: "10px", marginTop: "10px" }}>
            <button
              onClick={() => handleNav("auth")}
              className="btn ghost small"
              style={{ flex: 1 }}
            >
              Sign In
            </button>
            <button
              onClick={() => handleNav("signup")}
              className="btn small"
              style={{ flex: 1 }}
            >
              Sign Up
            </button>
          </div>
        </div>
