            display: none !important;
          }
          .mobile-toggle {
            display: block !important;
          }
        }
      `}</style>
    </header>
  );
};

import React, { useState, useEffect } from "react";
import { TopBar } from "./components/TopBar.js";
import { Footer } from "./components/Footer.js";
import { GuidedTourModal } from "./components/GuidedTourModal.js";
import { LandingPage } from "./pages/LandingPage.js";

// Helper for initial route from hash
function getInitialRoute(): string {
  if (typeof window !== "undefined" && window.location.hash) {
    const raw = window.location.hash.replace(/^#\/?/, "");
    const base = raw.split("/")[0];
    if (base) return base;
  }
  return "landing";
}

export const App: React.FC = () => {
  const [currentRoute, setCurrentRoute] = useState<string>(getInitialRoute);
  const [demoModalOpen, setDemoModalOpen] = useState<boolean>(false);

  // Sync hash changes with state
  useEffect(() => {
    const handleHashChange = () => {
      const route = getInitialRoute();
      setCurrentRoute(route);
    };

    window.addEventListener("hashchange", handleHashChange);
    return () => window.removeEventListener("hashchange", handleHashChange);
  }, []);

  const handleNavigate = (route: string, _params?: Record<string, string>) => {
    setCurrentRoute(route);
    if (typeof window !== "undefined") {
      window.location.hash = `#/${route === "landing" ? "" : route}`;
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        background: "var(--ink)",
        color: "var(--paper)",
        position: "relative",
      }}
    >
      {/* 1. Global Navigation TopBar */}
      <TopBar
        currentRoute={currentRoute}
        onRouteChange={handleNavigate}
        onOpenDemoModal={() => setDemoModalOpen(true)}
      />

      {/* 2. Page Content View */}
      <main style={{ flex: 1 }}>
        {currentRoute === "landing" || currentRoute === "" ? (
          <LandingPage
            onRouteChange={handleNavigate}
            onOpenDemo={() => setDemoModalOpen(true)}
          />
        ) : (
          <div
            className="animate-fade-in"
            style={{
              maxWidth: "1000px",
              margin: "60px auto",
              padding: "40px 24px",
              textAlign: "center",
            }}
          >
            <div className="panel" style={{ padding: "50px 30px" }}>
              <div className="eyebrow" style={{ color: "var(--gold)" }}>
                STAGE ROADMAP · PENDING STAGE APPROVAL
              </div>
              <h2 className="display" style={{ fontSize: "28px", color: "var(--cream)", margin: "14px 0" }}>
                {currentRoute.toUpperCase()} MODULE
              </h2>
              <p className="serif" style={{ fontSize: "18px", color: "#cdb78e", maxWidth: "600px", margin: "0 auto 24px" }}>
                In accordance with the strict handover rules, only Stage 1 (Shared Design System + Foundation + Landing Page)
                is currently active. Each subsequent page will be implemented individually upon explicit approval.
              </p>
              <div style={{ display: "flex", justifyContent: "center", gap: "12px", flexWrap: "wrap" }}>
                <button onClick={() => handleNavigate("landing")} className="btn">
                  ← Return to Landing Page
                </button>
                <button onClick={() => setDemoModalOpen(true)} className="btn secondary">
                  ✦ Open Guided Tour
                </button>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* 3. Global Footer */}
      <Footer onRouteChange={handleNavigate} />

      {/* 4. Global Interactive Guided Tour Modal */}
      <GuidedTourModal
        isOpen={demoModalOpen}
        onClose={() => setDemoModalOpen(false)}
        onNavigateCase={() => {
          setDemoModalOpen(false);
          handleNavigate("archive");
        }}
      />

      {/* 5. Ambient Candle Icon from Reference */}
      <div
        style={{
          position: "fixed",
          bottom: "16px",
          right: "16px",
          zIndex: 40,
          pointerEvents: "none",
          opacity: 0.85,
        }}
      >
        <img
          src="/candleon.png"
          alt="Altar candle"
          className="candle-glow"
          style={{ width: "24px", height: "44px", objectFit: "contain" }}
        />
      </div>
    </div>
  );
};

